14	    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
15	    await ui.setSetting(pg_uma, "note-threshold", "1.50");
16	    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-02-01", "to": "2026-02-10"})).toBe(true);
