20	    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(false);
21	    expect(await ui.pasteClaims(pg_uma, "Ada,30.00,2026-03-01,draft\nBen,5.00,,n")).toBe(2);
22	    const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
