content.content:
# Paste lines of name,amount,date,note: a DRAFT claim per line, in order, for the named person. Every line is
# checked with the claim form's rules before anything is written, so one refusal adds nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: lines
lines:
  class: net.officefloor.hq.app.claim.ValidatePaste
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: add
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithPaste
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** The paste box as typed: lines of name,amount,date,note, and the signed-in user (`by`) making the change. */
public record PasteRequest(String lines, String by) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPaste {
    public void respond(@Val PasteResponse result, ObjectResponse<PasteResponse> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * The paste box's lines of name,amount,date,note (the note may hold commas; the date may be blank for the sheet's
 * today; the note may be absent; blank lines are skipped). A note ending " #<reference>" gives the claim that
 * reference, not part of the note; a reference repeated within the paste refuses it. Each line's fields are checked with the claim form's
